public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) return true;
    }
    Set<Integer>[] dp = new Set[n / 2 + 1];
    for (int i = 1; i <= n / 2; i++) {
        dp[i] = new HashSet<>();
    }
    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int x : dp[i - 1]) {
                dp[i].add(x + num);
            }
        }
        dp[1].add(num);
    }
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i].contains(sum * i / n)) return true;
    }
    return false;
}

